using CarCareTracker.External.Interfaces;
using CarCareTracker.Models;
using Npgsql;
using System.Text.Json;

namespace CarCareTracker.External.Implementations
{
    public class PGFoodDataAccess : IFoodDataAccess
    {
        private NpgsqlDataSource pgDataSource;
        private readonly ILogger<PGFoodDataAccess> _logger;
        private static string scanTable = "food_scans";
        private static string profileTable = "food_profiles";
        public PGFoodDataAccess(IConfiguration config, ILogger<PGFoodDataAccess> logger)
        {
            pgDataSource = NpgsqlDataSource.Create(config["POSTGRES_CONNECTION"] ?? string.Empty);
            _logger = logger;
            try
            {
                string initCMD = $"CREATE SCHEMA IF NOT EXISTS app; " +
                    $"CREATE TABLE IF NOT EXISTS app.{scanTable} (id INT GENERATED BY DEFAULT AS IDENTITY primary key, householdId INT not null, data jsonb not null); " +
                    $"CREATE INDEX IF NOT EXISTS {scanTable}_household_idx ON app.{scanTable} (householdId); " +
                    $"CREATE TABLE IF NOT EXISTS app.{profileTable} (id INT primary key, data jsonb not null)";
                using (var ctext = pgDataSource.CreateCommand(initCMD))
                {
                    ctext.ExecuteNonQuery();
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
            }
        }
        public int AddScan(FoodScan scan)
        {
            try
            {
                using (var ctext = pgDataSource.CreateCommand($"INSERT INTO app.{scanTable} (householdId, data) VALUES(@householdId, CAST(@data AS jsonb)) RETURNING id"))
                {
                    ctext.Parameters.AddWithValue("householdId", scan.HouseholdId);
                    ctext.Parameters.AddWithValue("data", "{}");
                    scan.Id = Convert.ToInt32(ctext.ExecuteScalar());
                }
                return UpdateScan(scan) ? scan.Id : 0;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
                return 0;
            }
        }
        public bool UpdateScan(FoodScan scan)
        {
            try
            {
                using (var ctext = pgDataSource.CreateCommand($"UPDATE app.{scanTable} SET data = CAST(@data AS jsonb) WHERE id = @id AND householdId = @householdId"))
                {
                    ctext.Parameters.AddWithValue("id", scan.Id);
                    ctext.Parameters.AddWithValue("householdId", scan.HouseholdId);
                    ctext.Parameters.AddWithValue("data", JsonSerializer.Serialize(scan));
                    return ctext.ExecuteNonQuery() > 0;
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
                return false;
            }
        }
        private List<FoodScan> ReadScans(string cmd, Action<NpgsqlCommand> parameters)
        {
            var results = new List<FoodScan>();
            try
            {
                using (var ctext = pgDataSource.CreateCommand(cmd))
                {
                    parameters(ctext);
                    using (NpgsqlDataReader reader = ctext.ExecuteReader())
                        while (reader.Read())
                        {
                            var scan = JsonSerializer.Deserialize<FoodScan>(reader["data"] as string ?? "{}");
                            if (scan != null)
                            {
                                results.Add(scan);
                            }
                        }
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
            }
            return results;
        }
        public FoodScan? GetScan(int householdId, int id)
        {
            return ReadScans($"SELECT data FROM app.{scanTable} WHERE id = @id AND householdId = @householdId", x =>
            {
                x.Parameters.AddWithValue("id", id);
                x.Parameters.AddWithValue("householdId", householdId);
            }).FirstOrDefault();
        }
        public List<FoodScan> GetScans(int householdId, int limit)
        {
            return ReadScans($"SELECT data FROM app.{scanTable} WHERE householdId = @householdId ORDER BY id DESC LIMIT @limit", x =>
            {
                x.Parameters.AddWithValue("householdId", householdId);
                x.Parameters.AddWithValue("limit", limit);
            });
        }
        public bool DeleteScan(int householdId, int id)
        {
            try
            {
                using (var ctext = pgDataSource.CreateCommand($"DELETE FROM app.{scanTable} WHERE id = @id AND householdId = @householdId"))
                {
                    ctext.Parameters.AddWithValue("id", id);
                    ctext.Parameters.AddWithValue("householdId", householdId);
                    return ctext.ExecuteNonQuery() > 0;
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
                return false;
            }
        }
        public FoodProfile? GetProfile(int userId)
        {
            try
            {
                using (var ctext = pgDataSource.CreateCommand($"SELECT data FROM app.{profileTable} WHERE id = @id"))
                {
                    ctext.Parameters.AddWithValue("id", userId);
                    using (NpgsqlDataReader reader = ctext.ExecuteReader())
                        while (reader.Read())
                        {
                            return JsonSerializer.Deserialize<FoodProfile>(reader["data"] as string ?? "{}");
                        }
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
            }
            return null;
        }
        public bool SaveProfile(FoodProfile profile)
        {
            try
            {
                using (var ctext = pgDataSource.CreateCommand($"INSERT INTO app.{profileTable} (id, data) VALUES(@id, CAST(@data AS jsonb)) ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data"))
                {
                    ctext.Parameters.AddWithValue("id", profile.Id);
                    ctext.Parameters.AddWithValue("data", JsonSerializer.Serialize(profile));
                    return ctext.ExecuteNonQuery() > 0;
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
                return false;
            }
        }
        public bool DeleteProfile(int userId)
        {
            try
            {
                using (var ctext = pgDataSource.CreateCommand($"DELETE FROM app.{profileTable} WHERE id = @id"))
                {
                    ctext.Parameters.AddWithValue("id", userId);
                    return ctext.ExecuteNonQuery() > 0;
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
                return false;
            }
        }
    }
}
